const icons={arrow:'M4 12h16m-6-6 6 6-6 6',bag:'M5 7h14l1 14H4L5 7Zm3 0V5a4 4 0 0 1 8 0v2',chart:'M4 3v18h17M7 15l4-6 4 3 5-8',compare:'M8 4v16M16 4v16M3 8h10M11 16h10M5 6 3 8l2 2m14 4 2 2-2 2',car:'m3 11 2-6h14l2 6M3 11h18v8H3v-8Zm3 3h2m8 0h2M5 19v2m14-2v2',wrench:'m14 6 4-4a6 6 0 0 1-7 8L3 18a2 2 0 0 0 3 3l8-8a6 6 0 0 0 8-7l-4 4-4-4Z',flag:'M5 22V3m0 0c4-5 9 5 14 0v10c-5 5-10-5-14 0',shield:'m12 2 8 3v6c0 5-4 8-8 11-4-3-8-6-8-11V5l8-3Zm-4 9 3 3 5-6',file:'M6 2h8l4 4v16H6V2Zm7 0v6h5M9 12h6m-6 4h6',close:'m6 6 12 12M6 18 18 6',plus:'M12 4v16M4 12h16',book:'M3 3h7a2 2 0 0 1 2 2v16a2 2 0 0 0-2-2H3V3Zm18 0h-7a2 2 0 0 0-2 2v16a2 2 0 0 1 2-2h7V3Z',download:'M12 3v12m-5-5 5 5 5-5M4 15v6h16v-6',check:'m5 12 4 4L20 5',heart:'M12 21C-5 11 4-2 12 6c8-8 17 5 0 15Z'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[n]||icons.arrow}"/></svg>`;
const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>'¥'+Math.round(n).toLocaleString('zh-CN');
const baseProducts=[
 {id:'ohlins',brand:'ÖHLINS',name:'Road & Track DFV',model:'BMS MR40S1',fit:'BMW M2 F87',car:'f87',image:'assets/ohlins.jpg',price:18800,type:'ROAD + TRACK',structure:'单筒 / DFV 阀系',adjust:'25 格 · 压缩 / 回弹联动',use:'street',desc:'面向街道与赛道日的可调悬架方案。以 DFV 阀系、车型适配与调节方式作为选型起点。',source:'https://www.ohlins.com/en-us/automotive/road-and-track/bmw-m2-m3-m4-f87-f80-f82-2015?v=bmw-m2-2021'},
 {id:'kw',brand:'KW SUSPENSIONS',name:'Variant 3',model:'352200BH',fit:'BMW M2 F87',car:'f87',image:'assets/kw.jpg',price:16800,type:'STREET PERFORMANCE',structure:'双筒 / 独立阀系',adjust:'低速压缩 12 格 / 回弹 16 格',use:'street',desc:'针对街道驾驶的独立压缩与回弹调节方案。选型时一并确认车型配置、安装与定位要求。',source:'https://store.kwsuspensions.com/products/kw-coilover-kit-v3-352200bh/'},
 {id:'dssv',brand:'MULTIMATIC',name:'DSSV · Z/28 OE',model:'Camaro Z/28 原厂配套',fit:'Chevrolet Camaro Z/28',car:'z28',image:'assets/dssv.png',price:32800,type:'OE APPLICATION',structure:'DSSV 滑阀',adjust:'OE 车型专属标定',use:'track',desc:'以 Camaro Z/28 原厂应用理解 DSSV 滑阀技术。此处为 OE 方案预算，不代表通用改装套件或跨车型适配。',source:'https://www.multimatic.com/manufacturing/suspension/damping-technology'}
];
const products=[...baseProducts.map(p=>({...p,category:'suspension',unit:'套',priceBasis:'人民币参考预算，具体报价与安装条件需确认'})),...(window.AURORA_CATALOG_ADDITIONS||[]),...window.AuroraStore.concepts];
const articles={setup:{tag:'SETUP NOTES',title:'从用途开始，建立你的调校记录',body:'<p>通勤、山路与赛道日，对舒适性、响应和维护的要求不同。先写下你的使用场景，再看调节范围与安装条件。</p><h3>01 / 建立基线</h3><p>记录车型、轮胎、胎压、载荷、车高与当前调节位置。比较前保持这些条件一致，避免把条件变化误认为配件差异。</p><h3>02 / 一次只改一个变量</h3><p>按照产品说明书设定基准，每次小幅调整并保留记录；由专业人员确认定位、行程与安装情况。</p><h3>03 / 把感受变成可复核的记录</h3><p>用同一路段、同一测试流程记录车身加速度、轮荷与温度变化。个人驾驶感受可以补充数据，但不能代替同条件测试。</p>'},track:{tag:'TRACK GUIDE',title:'赛道日前，先完成这份准备清单',body:'<p>从可靠的车辆状态开始。性能配件只有在正确适配、安装和维护的前提下，才能发挥预期作用。</p><h3>车辆检查</h3><p>由专业人员检查轮胎、制动系统、紧固件、油液与渗漏；确认车辆符合场地要求。</p><h3>记录与复盘</h3><p>记录冷 / 热胎压、天气、载荷和每轮测试后的状态。比较圈速或主观感受时，保留这些背景条件。</p><h3>从体验回到选型</h3><p>把实际问题写进需求单：使用频率、当前不足、预算上限、维护能力。让配件选择服务于具体需求。</p>'}};
function readStored(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
const savedCart=readStored('aurora-cart',{});
const state={cart:Object.fromEntries(products.map(p=>[p.id,Math.min(20,Math.max(0,Number(savedCart[p.id])||0))])),compare:[],filters:{search:'',category:'all',brand:'all',sort:'featured',car:'all',budget:'all',use:'all'},metric:'force',imported:null,service:readStored('aurora-service',{}),favorites:readStored('aurora-favorites',[])};
function persist(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true}catch{toast('浏览器未允许保存，本次操作仍可继续。');return false}}
let toastTimer;
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2800)}
function hydrateIcons(){document.querySelectorAll('[data-icon]').forEach(el=>{el.innerHTML=icon(el.dataset.icon);el.removeAttribute('data-icon')})}
function cartTotal(){return products.reduce((n,p)=>n+p.price*(state.cart[p.id]||0),0)}
function cartCount(){return Object.values(state.cart).reduce((n,q)=>n+q,0)}
function updateCart(){persist('aurora-cart',state.cart);document.querySelector('#cart-count').textContent=cartCount()}
function addCart(id){state.cart[id]=Math.min(20,(state.cart[id]||0)+1);updateCart();toast('已加入选购清单 · 可继续咨询适配')}
function productCard(p){return window.AuroraStore.card(p,storeContext())}
function storeContext(){return {products,state,icon,modal}}
function sampleRows(){return Array.from({length:13},(_,i)=>{const x=(i-6)*50;return [x,Math.round(12*x+1500*Math.tanh(x/85)),Math.round(10*x+1250*Math.tanh(x/110)),Math.round(8*x+900*Math.tanh(x/120))]})}
const thermalRows=()=>[[20,100,100,100],[40,99,99.3,98.2],[60,97,98.5,96],[80,95,97,93],[100,92,95,90]];
function chartSVG(mini=false){const metric=mini?'force':state.metric;const rows=metric==='force'?(state.imported||sampleRows()):thermalRows();const w=700,h=310,left=65,right=20,top=25,bottom=45;const xs=rows.map(r=>r[0]),vals=rows.flatMap(r=>r.slice(1));const xmin=Math.min(...xs),xmax=Math.max(...xs),ymin=metric==='thermal'?85:Math.min(0,...vals),ymax=metric==='thermal'?102:Math.max(...vals);const X=x=>left+(x-xmin)/(xmax-xmin||1)*(w-left-right),Y=y=>h-bottom-(y-ymin)/(ymax-ymin||1)*(h-top-bottom);let inner='';for(let i=0;i<=4;i++){const y=ymin+(ymax-ymin)*i/4;inner+=`<path d="M${left} ${Y(y)}H${w-right}" stroke="#38432f" stroke-width="1"/><text x="${left-12}" y="${Y(y)+5}" text-anchor="end" fill="#98a48c" font-size="13">${Math.round(y).toLocaleString()}</text>`}for(let i=0;i<=4;i++){const x=xmin+(xmax-xmin)*i/4;inner+=`<text x="${X(x)}" y="${h-20}" text-anchor="middle" fill="#98a48c" font-size="13">${Math.round(x)}</text>`}const colors=['#b3f65a','#b29bec','#e4cc82'];colors.forEach((c,j)=>{inner+=`<polyline fill="none" stroke="${c}" stroke-width="3" points="${rows.map(r=>`${X(r[0])},${Y(r[j+1])}`).join(' ')}"/>`;rows.forEach(r=>{inner+=`<circle cx="${X(r[0])}" cy="${Y(r[j+1])}" r="3.5" fill="${c}"><title>Sample ${'ABC'[j]}: ${r[0]}, ${r[j+1]}</title></circle>`})});return `<svg class="${mini?'mini-chart':'large-chart'}" viewBox="0 0 ${w} ${h}" role="img" aria-label="${metric==='force'?'阻尼力与速度对比曲线，单位 N 和 mm/s':'温度与阻尼保持率模型计算曲线，单位摄氏度和百分比'}"><text x="${left}" y="14" fill="#aab79b" font-size="13">${metric==='force'?'Force / N':'Retention / %'}</text>${inner}<text x="${w-right}" y="${h-1}" text-anchor="end" fill="#aab79b" font-size="12">${metric==='force'?'Velocity / mm/s':'Temperature / °C'}</text></svg>`}
function legend(){return '<div class="legend"><span><i></i>Sample A</span><span><i></i>Sample B</span><span><i></i>Sample C</span></div>'}
function journey(){return `<div class="container"><div class="journey-strip">${[['flag','文化与体验','DISCOVER & CONNECT','#community'],['chart','数据辅助选型','COMPARE WITH CONTEXT','#lab'],['shield','少而精的配件','CURATED PERFORMANCE','#shop'],['wrench','适配与安装','FITMENT & SERVICE','#service']].map(([i,t,s,l])=>`<a class="journey-item" href="${l}">${icon(i)}<span><b>${t}</b><small>${s}</small></span></a>`).join('')}</div></div>`}
function home(){const picks=[products.find(p=>p.id==='ohlins'),products.find(p=>p.id==='aurora-formula-core'),...['tires','wheels','seats','brakes'].map(cat=>products.find(p=>p.category===cat))].filter(Boolean);return window.AuroraPages.home({products:picks,productCard,icon,journey})}
function intro(tag,title,copy,action=''){return `<div class="page-intro"><div><div class="eyebrow">${tag}</div><h1>${title}</h1><p>${copy}</p></div>${action}</div>`}
function shop(){return window.AuroraStore.render(storeContext())}
function filteredProducts(){return window.AuroraStore.filtered(storeContext())}
function refreshShop(){window.AuroraStore.refresh(storeContext())}
function lab(){return window.AuroraLab.render(products,state.compare)}
function service(){return `<div class="container">${intro('FITMENT & SERVICE','把选择，变成适合你的方案。','核对车型与用途，拆清预算，再把需求交给安装服务商。')}<div class="service-layout"><section class="panel"><h3>你的用车需求</h3><form id="service-form" style="margin-top:23px"><div class="form-grid"><label>车型<select name="vehicle" required><option value="">选择车型</option><option>BMW M2 F87</option><option>Chevrolet Camaro Z/28</option><option>其他车型 · 需核对适配</option></select></label><label>城市<input name="city" placeholder="例如：深圳" maxlength="50" required></label><label>主要用途<select name="purpose"><option>日常通勤 + 周末山路</option><option>街道 + 赛道日</option><option>封闭赛道体验</option></select></label><label>方案预算上限（元）<input name="budget" type="number" min="1000" max="1000000" step="100" value="25000" required></label><label>安装服务<select name="install"><option value="1800">安装 + 四轮定位 · 参考 ¥1,800</option><option value="0">仅配件 · 自行安排安装</option></select></label><label>5 年维护预留（元）<input name="maintenance" type="number" min="0" max="100000" step="100" value="5400" required></label><label class="full">备注<input name="notes" placeholder="例如：希望改善连续颠簸路面舒适性" maxlength="240"></label></div><p class="caption" style="margin-top:18px">需求单保存在当前浏览器，尚未发送给商家。你可以导出后交给服务商核对。</p><p class="form-error" id="service-warning"></p><div class="modal-actions"><button class="button ghost" type="button" data-action="save-service">保存草稿</button><button class="button primary" type="submit">${icon('download')} 导出需求单</button></div></form></section><aside><section class="panel"><div class="panel-title"><h3>方案预算</h3><button class="text-button" data-action="cart">编辑清单 ${icon('arrow')}</button></div><div id="budget-summary"></div></section><ol class="service-steps"><li><span class="step-number">01</span><span><b>确认适配</b>车型、配置、安装条件逐项核对。</span></li><li><span class="step-number">02</span><span><b>明确报价</b>区分配件、安装、定位与维护。</span></li><li><span class="step-number">03</span><span><b>记录与回访</b>保留安装记录和调校基线，形成复盘。</span></li></ol></aside></div></div>`}
function community(){return window.AuroraPages.community({icon,articles})}
function render(){window.AuroraPages?.unmount();window.AuroraLab?.unmount?.();const raw=location.hash.slice(1)||'home';const routes={home,shop,lab,community,service};const route=routes[raw]?raw:'home';document.querySelector('#app').innerHTML=routes[route]();document.body.dataset.route=route;document.querySelectorAll('[data-nav]').forEach(el=>{const active=el.dataset.nav===route;el.classList.toggle('active',active);if(active)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current')});document.title=({home:'发现极光',shop:'精选配件',lab:'性能评测',community:'汽车文化',service:'适配服务'}[route])+' — AURORA 极光';updateCart();hydrateIcons();window.AuroraPages.mount({modal,icon,route});window.AuroraStore.mount(storeContext());if(route==='shop'){['car','budget','use'].forEach(k=>document.querySelector('#filter-'+k).value=state.filters[k]);refreshShop()}if(route==='lab')window.AuroraLab.mount({products,compareIds:state.compare,toast,addCart});if(route==='service'){const form=document.querySelector('#service-form');for(const [k,v]of Object.entries(state.service)){if(form.elements[k])form.elements[k].value=String(v)}refreshBudget()}window.dispatchEvent(new CustomEvent('aurora-page-rendered',{detail:{route}}))}
function refreshChart(){const chart=document.querySelector('#lab-chart');if(!chart)return;chart.innerHTML=chartSVG();const force=state.metric==='force';document.querySelector('#chart-title').textContent=force?'Force × Velocity':'Thermal Stability';document.querySelector('#data-badge').textContent=force&&state.imported?'IMPORTED CSV':'MODEL DATA';document.querySelector('#file-status').textContent=force?(state.imported?'当前图表来自你导入的 CSV；测试条件由数据提供方确认。':'模型计算工况：相同温度 / 行程 / 档位；单位 N、mm/s。'):'选型参考：同速点阻尼保持率随温度变化；不对应品牌实测。';document.querySelector('#row-count').textContent=force?(state.imported||sampleRows()).length:thermalRows().length;document.querySelector('#stat-label').textContent=force?'Sample A · 最大绝对力':'100°C · Sample A 保持率';document.querySelector('#peak-force').textContent=force?Math.max(...(state.imported||sampleRows()).map(r=>Math.abs(r[1]))).toLocaleString()+' N':'92 %'}
function modal(title,body,actions=''){document.querySelector('#modal').classList.remove('photo-dialog','car-dialog','store-compare-dialog');document.querySelector('#modal-content').innerHTML=`<div class="modal-header"><h2>${title}</h2><button class="icon-button" data-action="close" aria-label="关闭弹窗">${icon('close')}</button></div>${body}${actions?`<div class="modal-actions">${actions}</div>`:''}`;const d=document.querySelector('#modal');if(!d.open)d.showModal()}
function details(id){const p=products.find(x=>x.id===id);if(p)window.AuroraStore.detail(p,storeContext())}
function showCart(){const selected=products.filter(p=>state.cart[p.id]);modal('选购清单',selected.length?selected.map(p=>`<div class="cart-row"><img src="${p.image}" alt="${p.name}"><div><h3>${p.name}</h3><p>${p.fit}<br>${money(p.price)} / ${escapeHTML(p.unit||'套')}</p></div><div class="qty"><button data-action="decrease" data-id="${p.id}" aria-label="减少 ${p.name} 数量">−</button><span>${state.cart[p.id]}</span><button data-action="increase" data-id="${p.id}" aria-label="增加 ${p.name} 数量">+</button></div></div>`).join('')+`<div class="summary-line total"><span>配件预算合计</span><b>${money(cartTotal())}</b></div><p class="caption">核对数量与计价单位后，可整理适配和报价需求。</p>`:'<p class="muted">先挑选你感兴趣的配件，再确认适配和安装。</p>',`<button class="button ghost" data-action="go-shop">继续选配件</button>${selected.length?'<button class="button primary" data-action="go-service">咨询适配与安装 →</button>':''}`)}
function toggleCompare(id){const i=state.compare.indexOf(id);if(i>=0)state.compare.splice(i,1);else{if(state.compare.length>=4){toast('一次可对比最多4款配件，请先移除一款');return}state.compare.push(id)}toast(i>=0?'已从对比中移除':'已加入规格对比');if(location.hash==='#shop')refreshShop();else if(!document.querySelector('#modal').open)render()}
function serviceData(){const form=document.querySelector('#service-form');return form?Object.fromEntries(new FormData(form)):state.service}
function fitmentWarning(data){const selected=products.filter(p=>state.cart[p.id]);if(data.vehicle&&selected.some(p=>['f87','z28'].includes(p.car)&&p.fit!==data.vehicle))return '清单中有专车型配件与所选车型不同，请先核对适配。';if(selected.some(p=>!['f87','z28'].includes(p.car)))return '轮胎、轮毂、座椅和定制件需逐项确认尺寸、孔距与接口。';return ''}
function refreshBudget(){const data=serviceData(),parts=cartTotal(),install=Number(data.install)||0,maintenance=Number(data.maintenance)||0;document.querySelector('#budget-summary').innerHTML=`<div class="summary-line"><span>${cartCount()} 件配件 · 参考预算</span><span>${money(parts)}</span></div><div class="summary-line"><span>安装与定位</span><span>${money(install)}</span></div><div class="summary-line total"><span>初期方案预算</span><b>${money(parts+install)}</b></div><div class="summary-line"><span>5 年维护预留</span><span>${money(maintenance)}</span></div><div class="summary-line"><span>5 年持有预算</span><strong>${money(parts+install+maintenance)}</strong></div><p class="caption">持有预算 = 配件 + 安装 + 维护预留；未计残值、融资与使用差异。</p>${parts+install>Number(data.budget)?'<p class="form-error">当前初期预算超过设定上限。</p>':''}${!parts?'<a class="text-button" style="margin-top:15px;color:var(--green)" href="#shop">先去选择配件 →</a>':''}`;document.querySelector('#service-warning').textContent=fitmentWarning(data)}
function download(name,text,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob(['\uFEFF',text],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000)}
function exportService(){const form=document.querySelector('#service-form');if(!form.reportValidity())return;const d=serviceData();state.service=d;persist('aurora-service',d);const parts=cartTotal(),install=Number(d.install)||0,maintenance=Number(d.maintenance)||0;download('AURORA_适配安装需求单.txt',`AURORA 极光 / 适配安装需求单\n本地生成，尚未发送给商家。所有价格均为选型参考。\n\n车型：${d.vehicle}\n城市：${d.city}\n用途：${d.purpose}\n预算上限：${money(d.budget)}\n备注：${d.notes||'无'}\n\n选购清单：\n${products.filter(p=>state.cart[p.id]).map(p=>`${p.brand} ${p.name} / ${p.model} / ${p.fit} × ${state.cart[p.id]}：${money(p.price*state.cart[p.id])}`).join('\n')||'尚未选择配件'}\n\n配件预算：${money(parts)}\n安装与定位：${money(install)}\n初期方案预算：${money(parts+install)}\n5 年维护预留：${money(maintenance)}\n5 年持有预算：${money(parts+install+maintenance)}\n\n适配提醒：${fitmentWarning(d)||'由服务商核对具体车型、配置与安装条件。'}\n\n服务商确认项：车型适配、最终含税报价、安装内容、四轮定位、质保与售后。`);toast('需求单已生成，可交给服务商核对')}
function showArticle(id){const a=articles[id];modal(a.title,`<div class="article-label">${a.tag}</div><div class="article-body">${a.body}</div>`,`<button class="button ghost" data-action="favorite" data-id="${id}">${icon('heart')} ${state.favorites.includes(id)?'已收藏':'收藏指南'}</button><button class="button primary" data-action="go-service">整理我的需求 →</button>`)}
function refill(id,key){const form=document.querySelector(id);const d=readStored(key,{});for(const [k,v]of Object.entries(d)){if(form.elements[k])form.elements[k].value=String(v)}}
function partner(){modal('一起，把性能说清楚。',`<p class="muted" style="font-size:13px;margin-bottom:20px">面向汽车 / 零部件品牌、改装及安装服务商。</p><form id="partner-form"><div class="form-grid"><label>品牌 / 机构<input name="brand" maxlength="80" required placeholder="你的品牌名称"></label><label>合作方式<select name="mode"><option>精选销售合作 / CPS</option><option>评测内容合作 / CPT</option><option>安装与售后服务</option><option>汽车文化节 / 体验活动</option></select></label><label class="full">合作方向<input name="direction" maxlength="240" placeholder="希望评测的产品、内容形式或服务城市" required></label></div><p class="caption" style="margin-top:20px">合作费率按项目协商。这里只保存 / 导出意向，不自动发送或签约。</p><div class="modal-actions"><button class="button primary" type="submit">保存并导出合作意向</button></div></form>`);refill('#partner-form','aurora-partner')}
function showEvent(){modal('汽车文化与体验',`<p class="muted" style="font-size:13px;margin-bottom:20px">记录你感兴趣的内容，活动时间、场地和安排另行确定。</p><form id="event-form"><div class="form-grid"><label>体验方向<select name="interest"><option>Dream Car 技术展示</option><option>汽车文化节</option><option>配件评测体验</option><option>调校与安装交流</option></select></label><label>所在城市<input name="city" placeholder="例如：深圳" required maxlength="50"></label></div><p class="caption" style="margin-top:20px">意向仅保存在当前浏览器，不代表报名成功。</p><div class="modal-actions"><button class="button primary" type="submit">保存我的意向</button></div></form>`);refill('#event-form','aurora-event')}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;e.preventDefault();const {action,id}=b.dataset;const actions={cart:showCart,details:()=>details(id),add:()=>addCart(id),compare:()=>toggleCompare(id),close:()=>document.querySelector('#modal').close(),'go-shop':()=>{document.querySelector('#modal').close();location.hash='shop'},'go-service':()=>{document.querySelector('#modal').close();location.hash='service'},increase:()=>{state.cart[id]=Math.min(20,state.cart[id]+1);updateCart();showCart();if(location.hash==='#service')refreshBudget()},decrease:()=>{state.cart[id]=Math.max(0,state.cart[id]-1);updateCart();showCart();if(location.hash==='#service')refreshBudget()},'reset-filters':()=>{state.filters={search:'',category:'all',brand:'all',sort:'featured',car:'all',budget:'all',use:'all'};render()},'clear-compare':()=>{state.compare=[];refreshShop()},'csv-template':()=>download('AURORA_force_velocity_template.csv','velocity,force_a,force_b,force_c\n'+sampleRows().map(r=>r.join(',')).join('\n'),'text/csv;charset=utf-8'),'reset-data':()=>{state.imported=null;refreshChart();toast('已恢复模型计算数据')},'save-service':()=>{state.service=serviceData();if(persist('aurora-service',state.service))toast('草稿已保存在当前浏览器')},article:()=>showArticle(id),favorite:()=>{state.favorites=Array.isArray(state.favorites)?state.favorites:[];const i=state.favorites.indexOf(id);if(i>=0)state.favorites.splice(i,1);else state.favorites.push(id);persist('aurora-favorites',state.favorites);showArticle(id)},partner,event:showEvent,'export-report':()=>{const list=state.compare.length?products.filter(p=>state.compare.includes(p.id)):products;download('AURORA_性能对比报告.txt','AURORA 极光 / 选型对比报告\n公开规格与模型计算数据分开；不同应用车型不可直接排名。\n\n'+list.map(p=>`${p.brand} ${p.name}\n车型：${p.fit}\n型号：${p.model}\n结构：${p.structure}\n调节：${p.adjust}\n参考预算：${money(p.price)}\n来源：${p.source}`).join('\n\n')+'\n\n当前图表：'+(state.metric==='force'?'阻尼力—速度':'热稳定性')+'\n来源：'+(state.metric==='force'&&state.imported?'用户导入 CSV，测试条件由提供方确认。':'设计模型计算数据，不对应品牌实测。')+'\n'+(state.metric==='force'?'velocity,force_a,force_b,force_c':'temperature_c,retention_a_pct,retention_b_pct,retention_c_pct')+'\n'+(state.metric==='force'?(state.imported||sampleRows()):thermalRows()).map(r=>r.join(',')).join('\n'));toast('对比报告已导出')}};actions[action]?.()});
document.addEventListener('input',e=>{if(e.target.id==='product-search'){state.filters.search=e.target.value;window.AuroraStore.resetLimit();refreshShop()}if(e.target.closest('#service-form'))refreshBudget()});
document.addEventListener('change',async e=>{const el=e.target;if(el.id.startsWith('filter-')){state.filters[el.id.replace('filter-','')]=el.value;window.AuroraStore.resetLimit();refreshShop()}if(el.id==='chart-metric'){state.metric=el.value;refreshChart()}if(el.closest('#service-form'))refreshBudget();if(el.id==='csv-input'&&el.files.length){try{const file=el.files[0];if(file.size>1000000)throw new Error('CSV 请控制在 1 MB 以内。');const raw=(await file.text()).replace(/^\uFEFF/,'').trim().split(/\r?\n/);const header=raw.shift().toLowerCase().replace(/\s/g,'');if(header!=='velocity,force_a,force_b,force_c')throw new Error('列名不匹配，请先下载模板。');if(raw.length<2||raw.length>1000)throw new Error('请导入 2–1,000 行数据。');const rows=raw.map(line=>{const parts=line.split(',').map(s=>s.trim());if(parts.length!==4||parts.some(s=>s===''))throw new Error('每行需要 4 个完整的数值。');const nums=parts.map(Number);if(nums.some(n=>!Number.isFinite(n)||Math.abs(n)>1000000))throw new Error('数据需为有效数值，绝对值不超过 1,000,000。');return nums}).sort((a,b)=>a[0]-b[0]);if(new Set(rows.map(r=>r[0])).size!==rows.length)throw new Error('速度列不能重复，请整理数据后重试。');state.imported=rows;state.metric='force';document.querySelector('#chart-metric').value='force';refreshChart();toast('CSV 已导入，图表与统计已更新')}catch(err){toast(err.message)}finally{el.value=''}}});
document.addEventListener('submit',e=>{if(e.target.id==='service-form'){e.preventDefault();exportService()}if(e.target.id==='partner-form'){e.preventDefault();const d=Object.fromEntries(new FormData(e.target));const saved=persist('aurora-partner',d);download('AURORA_品牌合作意向.txt',`AURORA 品牌合作意向\n本地草稿，尚未发送。\n品牌：${d.brand}\n方式：${d.mode}\n方向：${d.direction}`);document.querySelector('#modal').close();toast(saved?'合作意向已保存并导出，尚未发送':'合作意向已导出；浏览器未允许保存草稿')}if(e.target.id==='event-form'){e.preventDefault();if(persist('aurora-event',Object.fromEntries(new FormData(e.target)))){document.querySelector('#modal').close();toast('体验意向已保存在当前浏览器')}}});
document.querySelector('#modal').addEventListener('click',e=>{if(e.target===e.currentTarget){const r=e.currentTarget.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.currentTarget.close()}});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});
render();
